<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';Auth::require();BackupService::cleanup();
$error='';$message=(string)($_SESSION['backup_flash']??'');unset($_SESSION['backup_flash']);
if(isset($_GET['recovery'])){
 $name=(string)$_GET['recovery'];if(!preg_match('/^rollback-\d{8}-\d{6}-[a-f0-9]{12}\.pmb$/D',$name)||!in_array($name,BackupService::recoveries(),true)){http_response_code(404);exit('Backup not found.');}
 header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$name.'"');readfile(__DIR__.'/storage/'.$name);exit;
}
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!Security::verifyCsrf($_POST['_csrf']??null))throw new RuntimeException('Security check failed. Refresh the page, or check your hosting upload size limit.');
 $action=(string)($_POST['action']??'');
 if(in_array($action,['export','preview'],true)){
  if(!Auth::attempt((string)($_POST['current_password']??'')))throw new RuntimeException('Current app password is incorrect or attempts are temporarily limited.');$_SESSION['backup_reauth']=time();
 }
 if($action==='export'){
  $kind=(string)($_POST['kind']??'migration');if(!in_array($kind,['migration','settings'],true))throw new InvalidArgumentException('Invalid export mode.');
  $payload=BackupService::snapshot($kind==='migration');BackupService::validate($payload);
  if($kind==='migration'){$password=(string)($_POST['backup_password']??'');if($password!==(string)($_POST['confirm_password']??''))throw new InvalidArgumentException('Backup passwords do not match.');$bytes=BackupService::pack($payload,$password);$ext='pmb';}else{$bytes=json_encode($payload,JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);$ext='json';}
  if(strlen($bytes)>10485760)throw new RuntimeException('Backup exceeds 10 MiB.');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="PrivateMail-'.$kind.'-'.gmdate('Ymd-His').'.'.$ext.'"');echo $bytes;exit;
 }elseif($action==='preview'){
  $upload=$_FILES['backup_file']??null;if(!$upload||($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file((string)($upload['tmp_name']??'')))throw new InvalidArgumentException('Choose a backup file within your hosting upload limit.');
  if((int)$upload['size']>10485760)throw new InvalidArgumentException('Backup exceeds 10 MiB.');$bytes=file_get_contents($upload['tmp_name']);if($bytes===false)throw new RuntimeException('Unable to read upload.');
  $password=(string)($_POST['backup_password']??'');$data=BackupService::decode($bytes,$password);$mode=(string)($_POST['mode']??'merge');
  $next=BackupService::stage($data,$mode,$password);BackupService::discard($_SESSION['backup_preview']??null);$_SESSION['backup_preview']=$next;header('Location: /backup.php#preview',true,303);exit;
 }elseif($action==='cancel'){
  BackupService::discard($_SESSION['backup_preview']??null);unset($_SESSION['backup_preview']);header('Location: /backup.php',true,303);exit;
 }elseif($action==='apply'){
  $stage=$_SESSION['backup_preview']??null;if(!$stage||time()-(int)($_SESSION['backup_reauth']??0)>600)throw new RuntimeException('Preview expired. Upload again.');
  if(($stage['mode']??'')==='replace'&&($_POST['confirm_replace']??'')!=='1')throw new InvalidArgumentException('Confirm the replacement after reviewing the preview.');
  $data=BackupService::staged($stage);$recovery=BackupService::apply($data,(string)$stage['mode'],(string)($data['_recovery_password']??''),(string)$stage['view']);
  BackupService::discard($stage);unset($_SESSION['backup_preview'],$_SESSION['setup_wizard_step']);$_SESSION['backup_flash']='Import complete. Your local app password is unchanged. Reopen the inbox to sync mail.'.($recovery?' A recovery backup was saved below.':'');header('Location: /backup.php',true,303);exit;
 }else throw new InvalidArgumentException('Unknown backup action.');
}catch(Throwable $e){$error=$e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'Unable to complete backup operation. Check the file and private storage permissions.';}
$preview=$_SESSION['backup_preview']??null;if($preview&&($preview['expires']??0)<time()){BackupService::discard($preview);unset($_SESSION['backup_preview']);$preview=null;}
?>
